import{at as e,it as t,st as n,yt as r}from"./chunks/framework.B-d2E8F-.js";import{t as i}from"./chunks/DoctorSliceHero.YUMJV86N.js";var a=JSON.parse(`{"title":"LaTeX compilation environment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/latex-compilation.md","filePath":"guide/latex-compilation.md"}`),o=Object.assign({name:`guide/latex-compilation.md`},{setup(a){return(a,o)=>(r(),t(`div`,null,[o[0]||=e(`<h1 id="latex-compilation-environment" tabindex="-1">LaTeX compilation environment <a class="header-anchor" href="#latex-compilation-environment" aria-label="Permalink to “LaTeX compilation environment”">​</a></h1><p>Compiling previews, rendering standalone TikZ figures, and building <code>latexdiff</code> PDFs require a local LaTeX distribution.</p><h2 id="required-latex-distribution" tabindex="-1">Required LaTeX distribution <a class="header-anchor" href="#required-latex-distribution" aria-label="Permalink to “Required LaTeX distribution”">​</a></h2><p>Install a TeX distribution for your platform:</p><ul><li><strong>Windows</strong>: MiKTeX or TeX Live</li><li><strong>macOS</strong>: TeX Live (<code>brew install texlive</code>) or MacTeX</li><li><strong>Linux</strong>: TeX Live (<code>texlive-full</code> via your package manager)</li></ul><p>Make sure <code>latexmk</code> (preferred) or <code>pdflatex</code> is on your <code>PATH</code>. Run <code>texra doctor</code> to verify the toolchain in one pass:</p>`,6),n(i,{rows:[{state:`pass`,name:`LaTeX latexmk`,message:`LaTeX build orchestration`},{state:`pass`,name:`LaTeX pdflatex`,message:`PDFLaTeX compiler`},{state:`pass`,name:`LaTeX bibtex`,message:`BibTeX bibliography processing`},{state:`pass`,name:`LaTeX latexdiff`,message:`LaTeX diff generation`}]}),o[1]||=e(`<p class="hero-caption">The doctor&#39;s LaTeX rows confirm each binary is on PATH. The same check works for extension and CLI users alike.</p><p>Read the <a href="./installation.html">installation guide</a> for details on installing LaTeX and other dependencies such as Perl (required for <code>latexdiff</code>).</p><h2 id="integration-with-latex-workshop" tabindex="-1">Integration with LaTeX Workshop <a class="header-anchor" href="#integration-with-latex-workshop" aria-label="Permalink to “Integration with LaTeX Workshop”">​</a></h2><p>TeXRA works alongside the <a href="https://marketplace.visualstudio.com/items?itemName=James-Yu.latex-workshop" target="_blank" rel="noreferrer">LaTeX Workshop</a> extension, which provides compilation, previewing, and IntelliSense. If the extension isn&#39;t detected and your workspace contains LaTeX files, TeXRA prompts you to install it. On a workspace without LaTeX files there is no prompt; you can still install it from the Settings LaTeX tab.</p><p><strong>Workflow interaction:</strong></p><p>TeXRA uses LaTeX Workshop when available. For example, after generating a comparison file with its <code>latexdiff</code> features (read the <a href="./latex-diff.html">LaTeX diff guide</a>), TeXRA attempts to trigger LaTeX Workshop&#39;s build and view commands automatically, so you can compile and see the visualized changes in the resulting PDF.</p><p><strong>Recommended output directory (<code>%DIR%/build/</code>):</strong></p><p>To keep auxiliary build files (<code>.aux</code>, <code>.log</code>, <code>.pdf</code>) out of your source directory, open <strong>Settings → LaTeX → Recommended VS Code settings</strong> and click <strong>Apply all</strong>. This sets <strong>LaTeX Output Directory</strong> (<code>latex-workshop.latex.outDir</code>) to <code>%DIR%/build/</code> and adds <code>build/</code> to <strong>Explorer Auto-Reveal Exclude</strong>. You can also set <code>Latex-workshop: Latex: Out Dir</code> to <code>%DIR%/build/</code> directly in VS Code Settings (<code>Ctrl+,</code> / <code>Cmd+,</code>).</p><h2 id="alternative-online-compilers-e-g-overleaf" tabindex="-1">Alternative: online compilers (e.g., Overleaf) <a class="header-anchor" href="#alternative-online-compilers-e-g-overleaf" aria-label="Permalink to “Alternative: online compilers (e.g., Overleaf)”">​</a></h2><p>If you do not want a local TeX distribution, you can upload the <code>.tex</code> files generated by TeXRA (such as <code>_diff.tex</code> files or standalone TikZ files) to <a href="https://www.overleaf.com" target="_blank" rel="noreferrer">Overleaf</a> or sync via Git (see <a href="./working-with-overleaf.html">Working with Overleaf</a>).</p>`,10)]))}});export{a as __pageData,o as default};